def tables(D):
    rows = []
    for key, lab in [('causal_all', 'Causal transfer (linear)'), ('nl_all', 'Causal transfer (nonlinear)'), ('minimal_all', 'GBM minimal'), ('minimal_loc_all', 'GBM minimal + location'), ('partial_all', 'GBM partial'),
                     ('full_all', 'GBM full'), ('full_loc_all', 'GBM full + location'), ('full_mono_all', 'GBM full, monotone'), ('full_joint_all', 'GBM full, mediators shifted'), ('zone_baseline', 'Zone baseline')]:
        d = DEC.get(key); mk = key.replace('_all', ''); ch = CH.get(f'six|{mk}', {}).get('rho')
        rows.append([lab, B(ch) if ch else '—', m(d['median']), B(d['mae']), f"{pct(d['tercile_agree'][0])} ({pct(d['tercile_agree'][1])}–{pct(d['tercile_agree'][2])})", pct(d['top_recall']), pct(d['gross_misclass']), m(d['rho'])])
    D.table(['Model', 'ρ, change 1985–2025 (six out)', 'Answer to +10 pp (°C)', 'MAD vs own total (°C)', 'Right third of cities', 'Top third found', 'Off by two thirds', 'ρ with own total'],
            rows, widths_mm=[34, 24, 17, 22, 24, 15, 15, 14], size=7,
            caption=f"**Table 1 | Transfer of sealing effects to cities on unseen continents and its use for screening.** ρ change, median Spearman correlation of predicted and observed change of heat-island intensity in held-out cities; other columns refer to the continent-out intervention test (+10 pp impervious cover, everything else fixed), with medians or means over {DEC['causal_all'].get('n', 126) if isinstance(DEC['causal_all'], dict) and 'n' in DEC['causal_all'] else 126} cities and 95% bootstrap intervals over cities. Thirds are defined by the cities' own total effects. MAD, mean absolute difference. Own effects are assumption-dependent benchmarks, not ground truth.")


def ed_table(D):
    D.table(['Layer and question', 'Estimand or quantity', 'Conditioning set', 'What is held fixed', 'Evidence in this study'],
            [['Prediction: how hot is a place, how did heat change?', 'E[HI | surface, terrain, climate]', 'Any predictors', 'Nothing; association', 'Transfer of 1985–2025 change (Fig. 3)'],
             ['Intervention: +10 pp sealing, vegetation responds', 'Total effect θ', 'Terrain, location (W)', 'W; mediators respond', 'Within-city DML; checks (Figs. 1, 2)'],
             ['Intervention: +10 pp sealing, vegetation kept', 'Direct effect', 'W + NDVI, albedo, tree cover', 'W and mediators', 'Within-city DML (Fig. 1c)'],
             ['Intervention: +10 pp across a 1-km neighbourhood', 'Neighbourhood effect', 'W + own-cell ISA', 'W, own cell', 'Joint DML (Fig. 2c)'],
             ['Model-implied contrast', 'f(ISA + 0.1, ·) − f(ISA, ·)', 'Model features', 'All other features', 'GBM answers (Fig. 4)'],
             ['Transport to unseen cities', 'τ(V), V = cell and climate modifiers', 'Within-city residuals', 'Modifiers V', 'Continent-out tests (Fig. 4, Table 1)'],
             ['Decision: which option?', 'Not estimated', '—', '—', 'Layers and caveats (Fig. 5c)']],
            widths_mm=[38, 30, 30, 28, 33], caption='**Extended Data Table 1 | Planning questions, estimands and conditioning sets.** pp, percentage points; HI, heat-island intensity; ISA, impervious cover; W, terrain and 5-km location bins; V, effect modifiers.')


def build():
    D = Doc(refs=REFS)
    D.para(f'**{TITLE}**', size=14, after=12)
    D.para('Author names and affiliations withheld for double-anonymous review', after=12)
    D.h('Abstract', 1); D.para(ABSTRACT)
    D.h('Main', 1)
    for p in INTRO: D.para(p, after=6)
    D.h('Results', 1)
    for t, ps in [('The heat cost of sealing within cities', R1), ('What the checks support', R2), ('Predicting change and answering an intervention are different tasks', R3T),
                  ('Transferred effects and screening', R4), ('Heat cost of sealing under climates projected to 2100', R6)]:
        D.h(t, 2)
        for p in ps: D.para(p, after=6)
    D.h('Discussion', 1)
    for p in DISC: D.para(p, after=6)
    D.h('Limitations and future directions', 2); D.para(LIMS, after=6)
    D.h('Conclusions', 2); D.para(CONCL, after=6)
    D.h('Methods', 1)
    for t, ps in METHODS:
        D.h(t, 2)
        for p in ps: D.para(p, after=6)
        if t == 'Within-city causal effects': D.equation(*EQ[0])
        if t == 'Transfer models and tests': D.equation(*EQ[1])
    D.h('Data availability', 1)
    D.para("All input data are openly available: Landsat Collection 2 Level-2, ESA WorldCover 2021, Copernicus GLO-30 DEM, ESA CCI land cover, LCMAP CONUS v1.3, TerraClimate and NEX-GDDP-CMIP6 through the Microsoft Planetary Computer (https://planetarycomputer.microsoft.com), and GlobPOP through Zenodo. Source data for all figures and tables, the city-level estimates and the sampled cell tables are provided with this paper and will be deposited in a public repository upon acceptance.")
    D.h('Code availability', 1)
    D.para("All code for data download, compositing, back-casting, within-city estimation, transfer tests, simulations, projections, figures and tables is provided as Supplementary Software and will be archived with a DOI upon acceptance.")
    D.references()
    D.h('Acknowledgements', 1); D.para('[To be added after review.]')
    D.h('Author contributions', 1); D.para('[To be added after review.]')
    D.h('Competing interests', 1); D.para('The authors declare no competing interests.')
    D.pagebreak(); D.h('Tables', 1); tables(D)
    D.pagebreak(); D.h('Figures', 1)
    for i in range(1, 6): D.figure(f'{FIG}/Fig{i}.png', FIGCAP[i])
    D.pagebreak(); D.h('Extended Data', 1)
    for i in range(1, 10): D.figure(f'{FIG}/ED_Fig{i}.png', ED[i])
    ed_table(D)
    D.save(f'{OUT}/Manuscript_126_cities_NatSustain.docx')
    wc = lambda ps: sum(len(re.sub(r'\[@[^\]]+\]', '', p).split()) for p in ps)
    main = INTRO + R1 + R2 + R3T + R4 + R6 + DISC + [LIMS, CONCL]
    print('title chars', len(TITLE), 'abstract', len(ABSTRACT.split()), 'main', wc(main), 'methods', wc(list(itertools.chain(*[p for _, p in METHODS]))), 'refs', len(D.order))
    json.dump(dict(order=D.order), open(f'{OUT}/ref_order_ns.json', 'w'))


if __name__ == '__main__':
    build()
